// Task registry: task_ids / make_task / reference_circuit.
// Tasks self-register from their own .cpp with SPIKE_REGISTER_TASK (see tasks.h), so new chapters add files,
// never edit this one. Order: by registration `order` key, then id.
#include <algorithm>
#include <array>
#include <map>
#include <string>
#include <vector>
#include "spike/task.h"
#include "tasks.h"
#include "task_anchors.inc"  // generated by CMake: references every task object file

namespace spike
{
namespace tasks
{
std::vector< Entry >& registry()
{
  static volatile int keep = spike_task_anchors();  // forces the linker to keep every task object
  (void)keep;
  static std::vector< Entry > r;
  return r;
}
Registrar::Registrar( Entry e ) { registry().push_back( std::move( e ) ); }
} // namespace tasks

static std::vector< tasks::Entry > sorted()
{
  auto r = tasks::registry();
  std::sort( r.begin(), r.end(), []( auto& a, auto& b ) { return a.order != b.order ? a.order < b.order : a.id < b.id; } );
  return r;
}

std::vector< std::string > task_ids()
{
  std::vector< std::string > ids;
  for ( auto& e : sorted() ) ids.push_back( e.id );
  return ids;
}

namespace
{
/// Every task the registry hands out is wrapped in this guard (honesty contract: a level is passed by the mechanism it teaches, with the stimuli it owns).
///   * the circuit may feed the level only through the level's own sensors: an input channel that sensor_channels() does not list (a recorded spike train, an extra generator) is a
///     circuit that brings its own stimulus, and a "spike_generator" input is never a sensor of any level (tasks drive their sensors with set_input(), which a spike train refuses);
///   * a run on such a circuit never passes, never scores above kNoMechanismCap, and says so;
///   * a run that did not pass never shows 100 (a gate that failed a task whose criteria were all met still reads below the pass mark's full score).
/// Everything else is forwarded unchanged. The check runs once, at the first slice after reset().
class Guarded : public Task
{
public:
  explicit Guarded( std::unique_ptr< Task > t ) : t_( std::move( t ) ) {}

  std::string id() const override { return t_->id(); }
  std::string title() const override { return t_->title(); }
  std::string brief() const override { return t_->brief(); }
  std::vector< std::string > sensor_channels() const override { return t_->sensor_channels(); }
  std::vector< std::string > motor_channels() const override { return t_->motor_channels(); }
  double duration_ms() const override { return t_->duration_ms(); }
  double quick_duration_ms() const override { return t_->quick_duration_ms(); }
  void set_quick( bool q ) override
  {
    Task::set_quick( q );
    t_->set_quick( q );
  }
  void reset( uint64_t seed ) override
  {
    audited_ = false;
    reject_.clear();
    t_->reset( seed );
  }
  void step( Engine& e, double dt_ms ) override
  {
    if ( !audited_ )
      audit( e );
    t_->step( e, dt_ms );
  }
  BodyState body() const override { return t_->body(); }
  Score score() const override
  {
    Score s = t_->score();
    if ( bad_mode_ || bad_variant_ )
    {
      s.passed = false;
      s.value = 0.0;
      s.verdict = bad_mode_ ? "Unknown difficulty mode: use guided, standard or researcher." : "Unknown challenge variant: this level does not list it.";
      s.parts[ "bad_request" ] = 1.0;
    }
    else if ( !reject_.empty() )
    {
      s.passed = false;
      s.value = std::min( s.value, 49.0 );
      s.verdict = reject_;
      s.parts[ "circuit_rejected" ] = 1.0;
    }
    else if ( !s.passed )
      s.value = std::min( s.value, 99.0 );
    return s;
  }
  std::array< double, 4 > world_bounds() const override { return t_->world_bounds(); }
  double field( double x, double y ) const override { return t_->field( x, y ); }
  std::string chapter() const override { return t_->chapter(); }
  std::string view() const override { return t_->view(); }
  int par_neurons() const override { return t_->par_neurons(); }
  int par_slack() const override { return t_->par_slack(); }
  std::string parent() const override { return t_->parent(); }
  Challenge challenge() const override { return t_->challenge(); }
  std::vector< Event > timeline() const override { return t_->timeline(); }
  std::vector< Band > bands() const override { return t_->bands(); }
  std::vector< std::string > modulators() const override { return t_->modulators(); }
  std::map< std::string, ChannelKind > channel_kinds() const override { return t_->channel_kinds(); }
  std::string level_kind() const override { return t_->level_kind(); }
  std::vector< std::string > concepts_new() const override { return t_->concepts_new(); }
  std::vector< std::string > concepts_used() const override { return t_->concepts_used(); }
  bool on_spine() const override { return t_->on_spine(); }
  void set_mode( const std::string& mode ) override
  {
    Task::set_mode( mode );
    bad_mode_ = mode != "guided" && mode != "standard" && mode != "researcher";
    t_->set_mode( mode );
  }
  std::map< std::string, std::string > variants() const override { return t_->variants(); }
  void set_variant( const std::string& v ) override
  {
    Task::set_variant( v );
    // a challenge variant must be one the level lists (a diagnosis case, and a prediction bet (Diagnosis::bet), carry the submitted answer in this slot and judge it themselves)
    bad_variant_ = !v.empty() && t_->level_kind() != "diagnosis" && !t_->diagnosis().bet && !t_->variants().count( v );
    t_->set_variant( v );
  }
  std::vector< Hint > hints() const override { return t_->hints(); }
  std::map< std::string, Metric > metrics() const override { return t_->metrics(); }
  double next_event_ms( double t_ms ) const override { return t_->next_event_ms( t_ms ); }
  Diagnosis diagnosis() const override { return t_->diagnosis(); }
  Note notebook() const override { return t_->notebook(); }
  std::string default_model() const override { return t_->default_model(); }
  std::string recipe() const override { return t_->recipe(); }
  Given given() const override { return t_->given(); }

private:
  void audit( Engine& e )
  {
    audited_ = true;
    const auto own = t_->sensor_channels();
    for ( const auto& in : e.inputs() )
      if ( in.kind == "spike_generator" || std::find( own.begin(), own.end(), in.name ) == own.end() )
      {
        reject_ = "The circuit brings a stimulus of its own: it has an input that this level does not drive (a recorded spike train, an extra generator, a noise source added on the "
                  "sandbox bench). That is why this run cannot pass and its score is held below the pass mark, whatever the circuit does. A level is scored with its own sensors only: "
                  "delete that input and wire the sensors the brief names.";
        return;
      }
    audit_locked( e );
  }
  /// A locked-wiring level (Task::given): the circuit must be the given one in everything that is locked or not free, and every free value must lie in its range. The verdicts name
  /// no numbers; which part differs is told by section (the digests of LockedDigest), not by value.
  void audit_locked( Engine& e )
  {
    const Given g = t_->given();
    if ( g.digest.empty() )
      return;
    const LockedDigest d = e.locked_digest();
    const char* tail = " Load the given circuit again and set only the controls the level marks free.";
    if ( d.pops != g.digest.pops )
      reject_ = std::string( "The given cells were changed: a locked population was resized, removed, given another model or other parameters, or one was added. In this level the cells are data." ) + tail;
    else if ( d.wiring != g.digest.wiring )
      reject_ = std::string( "The given wiring was changed: a locked connection was added, removed, re-weighted or re-timed. In this level the wiring is data and cannot be edited." ) + tail;
    else if ( d.types != g.digest.types )
      reject_ = std::string( "A cell type was changed in a way this level does not allow: only the sign and the scale the level marks free can be set, and its cell types cannot be added, removed or regrouped." ) + tail;
    else if ( d.channels != g.digest.channels )
      reject_ = std::string( "The level's inputs and outputs were changed: they are part of the given circuit." ) + tail;
    else
    {
      for ( const auto& gi : e.structure().groups )
        if ( !gi.scale_in_range )
        {
          reject_ = "A free scale is outside the range this level allows for its cell type, so the circuit cannot be scored. Bring it back inside the range the card shows.";
          return;
        }
    }
  }
  std::unique_ptr< Task > t_;
  bool audited_ = false, bad_mode_ = false, bad_variant_ = false;
  std::string reject_;
};
}  // namespace

std::unique_ptr< Task > make_task( const std::string& id )
{
  for ( auto& e : tasks::registry() )
    if ( e.id == id ) return std::make_unique< Guarded >( e.make() );
  return nullptr;
}

std::string reference_circuit( const std::string& id )
{
  for ( auto& e : tasks::registry() )
    if ( e.id == id ) return e.circuit;
  return "";
}

} // namespace spike
